def localize_info(base, language):
    if language == "en":
        return base
    source = TRANSLATIONS[language]
    info = deepcopy(base)
    info["language"] = language
    info["translation_status"] = "draft_unreviewed"
    info["i18n_status"][language] = "draft_unreviewed"
    info["disclaimer"]["text"] = {
        "kn": "ಈ ಅಪ್ಲಿಕೇಶನ್ ಫೋಟೋದಿಂದ ಪ್ರಾಥಮಿಕ ಅಂದಾಜು ನೀಡುತ್ತದೆ; ಅದು ತಪ್ಪಾಗಬಹುದು. ಕೃಷಿ ಅಧಿಕಾರಿ ಅಥವಾ ಕೃಷಿ ವಿಜ್ಞಾನ ಕೇಂದ್ರದ ತಜ್ಞರ ಸಲಹೆಗೆ ಇದು ಬದಲಿಯಲ್ಲ.",
        "hi": "यह ऐप फोटो से शुरुआती अनुमान देता है और गलत हो सकता है। यह कृषि अधिकारी या कृषि विज्ञान केंद्र के विशेषज्ञ की सलाह का विकल्प नहीं है।",
        "ml": "ഈ ആപ്പ് ചിത്രത്തിൽ നിന്ന് പ്രാഥമിക വിലയിരുത്തൽ നൽകുന്നു; അത് തെറ്റാം. ഇത് കൃഷി ഉദ്യോഗസ്ഥന്റെയോ കൃഷി വിജ്ഞാന കേന്ദ്രത്തിലെ വിദഗ്ധന്റെയോ ഉപദേശത്തിന് പകരമല്ല.",
    }[language]
    info["translation_scope"] = "Concise field-guide summaries; chemical recipes and historical doses are not included in regional summaries."
    info["explanation"]["templates"].update(source["templates"])
    info["explanation"]["positions"] = dict(zip(base["explanation"]["positions"], source["positions"]))
    info["uncertain_result"]["what_to_do"] = [{"text": text, "sources": []} for text in source["uncertain"]]
    for class_id, translated in source["classes"].items():
        entry = info["classes"][class_id]
        entry["display_name"], entry["short_name"] = translated["name"], translated["short"]
        entry["summary"] = {"text": translated["summary"], "sources": base["classes"][class_id]["summary"].get("sources", [])}
        entry["limits"] = {"text": translated["limits"], "sources": []}
        for field, key in [("check_signs", "signs"), ("possible_causes", "causes"), ("what_to_do", "actions"), ("when_to_get_help", "help")]:
            entry[field] = [{"text": text, "sources": ["S2"]} for text in translated.get(key, [])]
        entry["also_consider"] = [{"name": name} for name in translated.get("alternatives", [])]
    return info
